B.d3a=new A.e(B.kF,["wfx_leg_shp1","wfp_legend","A big pale box is a CONTAINER: what sits inside it physically lives inside it - the five JSON docs in an applet definition, the three bundle:* rows inside SqfliteStore, the eight sinks inside SyncHub.","text",480,136,600,56,10,12],t.M)
B.d3g=new A.e(B.kF,["wfx_leg_shp2","wfp_legend","A small solid box is one node. Tap it to read the full description; each one names the file or symbol it came from.","text",480,204,600,40,10,12],t.M)
B.d3e=new A.e(B.kF,["wfx_leg_shp3","wfp_legend","An arrow is a FLOW: data actually moves that way, and its label says WHAT moves. Containment is never drawn as an arrow.","text",480,256,600,40,10,12],t.M)
B.d3j=new A.e(B.kF,["wfx_leg_shp4","wfp_legend","Arrow labels are cut to 18 characters to fit the canvas label chip. The full wording is in the inventory doc.","text",480,308,600,40,10,12],t.M)
