B.dNH=new A.t("parentColumn",B.w,"Graph/dag: physical containment column on the nodes table \u2014 a nested node ranks one column right of its parent and connects with a soft DASHED (arrowless) line, distinct from the data edges.",B.f,null,!1)
B.dN0=new A.t("collapsible",B.W,'Graph/dag (needs parentColumn): a node with nested children shows a collapse/expand toggle; collapsing hides its whole contained subtree and shows a "+N" badge (N = hidden descendants). Session-only, not persisted.',B.f,null,!1)
B.dFF=new A.t("sketchTable",B.ax,"Enable a freehand SKETCH overlay (draw/write/add text on top of the diagram). Strokes persist as JSON in this table's first row.",B.f,null,!1)
