B.dyz=new A.t("fontFamily",B.C,"Font for rank/court letters (suits are vector-drawn). Default: system.",B.f,null,!1)
B.dBn=new A.t("onTap",B.S,"Card-tap action spec { fn, args }.",B.f,null,!1)
B.dDu=new A.t("action",B.S,"Alias for `onTap` (card-tap action spec { fn, args }); either name works.",B.f,null,!1)
