B.df0=new A.db("cardtable","A felt table of real playing-card faces, grouped into piles from a table of card rows (one row per card). Cards slide between piles and flip on faceUp changes; rules stay in the data functions.",B.bqN,!1)
B.dwf=new A.t("table",B.ax,"Dice table (one row per die).",B.f,null,!1)
B.dIJ=new A.t("valueColumn",B.w,'Numeric face-value column (default "value").',B.f,null,!1)
B.dJb=new A.t("heldColumn",B.w,"Optional bool column; held dice show a ring and do not tumble.",B.f,null,!1)
B.dAQ=new A.t("sides",B.aj,"Die sides, for the roll-through flash (default 6).",B.f,null,!1)
B.dFA=new A.t("dieSize",B.aj,"Die edge in logical px (default 64).",B.f,null,!1)
