B.dtX=new A.t("collectionId",B.C,"Which collection to rank (or injected as rowId by a host).",B.f,null,!1)
B.dCR=new A.t("tierlistTable",B.ax,'Table persisting tier lists (default "tierlists").',B.f,null,!1)
B.dAs=new A.t("tierlistCollectionColumn",B.w,"Column in tierlistTable holding the collection id a saved tier layout belongs to (default collectionId).",B.f,null,!1)
B.dtZ=new A.t("tierlistId",B.C,"Explicit tierlist row; otherwise found/created by collection.",B.f,null,!1)
B.dB2=new A.t("tiersColumn",B.w,'Tierlist JSON tiers [{key,label,color}] (default "tiers").',B.f,null,!1)
B.dPF=new A.t("placementsColumn",B.w,'Tierlist JSON {tier:[itemId,\u2026]} (default "placements").',B.f,null,!1)
B.bWQ=s([B.dtX,B.avu,B.avV,B.avT,B.dCR,B.dAs,B.dtZ,B.dB2,B.dPF],t.G)
B.dfU=new A.db("tierlist","Drag a collection's items from a tray into ranked tiers (S/A/B/C/D, customizable). Placement persists to a tierlists row as JSON.",B.bWQ,!1)
B.bOo=s(["feed","map","sources"],t.s)
B.dIc=new A.t("view",B.bA,"Which surface to show.",B.bOo,null,!1)
B.dtl=new A.t("base",B.C,"https base URL of the news files (e.g. https://host/news/). The node talks to this one host only.",B.f,null,!1)
B.dzB=new A.t("accent",B.C,"Accent color #RRGGBB (default: theme primary).",B.f,null,!1)
B.dLl=new A.t("storyScreen",B.C,'Screen opened on a story tap (default "story"); the node first fills the `articles` table and selects the `stories` row.',B.f,null,!1)
B.dB_=new A.t("openStory",B.S,"Action fired with the tapped `stories` row (after the node fills the `articles` table), e.g. {chain:[{fn:selectRow},{fn:goto,args:{screen:story}}]}. Absent: selectRow + goto storyScreen.",B.f,null,!1)
B.dwt=new A.t("mapScreen",B.C,'Screen the "Map \u2192" link opens.',B.f,null,!1)
B.dyx=new A.t("sourcesScreen",B.C,'Screen the "All N outlets \u2192" link opens.',B.f,null,!1)
B.dDt=new A.t("geojsonAsset",B.C,"Bundled world-countries GeoJSON (feature property `iso2`) for the map view.",B.f,null,!1)
B.avp=new A.t("strings",B.S,"Optional per-key {lang: text} overrides of the built-in UI strings.",B.f,null,!1)
